#pragma once

#include <cstddef>
#include <cstdint>

namespace grandleon::nintendo64::sevenfold_terrain_renderer {

struct UV final {
    std::int16_t s;
    std::int16_t t;
};

// Builds the 32x32 CI4 character material atlas and loads the two original
// 64x64 CI4 terrain-quality atlases generated by the pinned asset script. The
// material palettes are deliberately greyscale: RDPQ_COMBINER_TEX_SHADE
// multiplies them by existing vertex colours rather than replacing terrain,
// team, or style identity.
[[nodiscard]] bool initialize();
void bind_terrain();
void bind_character();

// Screen-space alpha-clipped props are a separate, grouped pass. They enrich
// fixed-camera board edges and close backgrounds without changing tactical
// geometry, hit testing, or the production campaign path.
void draw_board_props(bool compact);
void draw_close_props(std::uint8_t terrain);
void draw_capture_floor_strip();

[[nodiscard]] std::size_t terrain_peak_texture_bytes() noexcept;
[[nodiscard]] std::size_t terrain_embedded_bytes() noexcept;

[[nodiscard]] UV character_uv(
    const std::int16_t points[3][3], int corner, std::uint8_t material
) noexcept;

[[nodiscard]] UV terrain_uv(
    const std::int16_t points[3][3], int corner, std::uint8_t region,
    std::uint8_t variation = 0
) noexcept;

}  // namespace grandleon::nintendo64::sevenfold_terrain_renderer
